#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int w;
    int idx;
} Node;

int cmp(const void *a, const void *b) {
    const Node *na = (const Node *)a;
    const Node *nb = (const Node *)b;
    if (na->w != nb->w) return na->w - nb->w;
    return na->idx - nb->idx;
}

int *parent, *head, *tail, *nxt;
long long *comp_sum, *ans;
char *active;
int N, M, K;

int find(int x) {
    if (parent[x] != x) parent[x] = find(parent[x]);
    return parent[x];
}

int main() {
    scanf("%d %d", &N, &M);
    K = N * M;

    Node *nodes = (Node *)malloc(K * sizeof(Node));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int idx = i * M + j;
            int w;
            scanf("%d", &w);
            nodes[idx].w = w;
            nodes[idx].idx = idx;
        }
    }

    qsort(nodes, K, sizeof(Node), cmp);

    parent = (int *)malloc(K * sizeof(int));
    head = (int *)malloc(K * sizeof(int));
    tail = (int *)malloc(K * sizeof(int));
    nxt = (int *)malloc(K * sizeof(int));
    comp_sum = (long long *)malloc(K * sizeof(long long));
    ans = (long long *)malloc(K * sizeof(long long));
    active = (char *)malloc(K * sizeof(char));

    for (int i = 0; i < K; i++) {
        parent[i] = i;
        head[i] = tail[i] = -1;
        nxt[i] = -1;
        ans[i] = -1;
        active[i] = 0;
    }

    for (int i = 0; i < K; i++) {
        int v = nodes[i].idx;
        int w = nodes[i].w;

        active[v] = 1;
        parent[v] = v;
        comp_sum[v] = w;
        head[v] = tail[v] = v;
        nxt[v] = -1;

        int r = v / M;
        int c = v % M;
        int neigh[4];
        int cnt = 0;

        if (r > 0) neigh[cnt++] = v - M;
        if (r + 1 < N) neigh[cnt++] = v + M;
        if (c > 0) neigh[cnt++] = v - 1;
        if (c + 1 < M) neigh[cnt++] = v + 1;

        int roots[4];
        int nroots = 0;
        long long total = w;

        for (int k = 0; k < cnt; k++) {
            int u = neigh[k];
            if (!active[u]) continue;

            int ru = find(u);

            int dup = 0;
            for (int j = 0; j < nroots; j++) {
                if (roots[j] == ru) {
                    dup = 1;
                    break;
                }
            }
            if (dup) continue;

            roots[nroots++] = ru;
            total += comp_sum[ru];

            if (comp_sum[ru] < w) {
                for (int node = head[ru]; node != -1; node = nxt[node]) {
                    ans[node] = comp_sum[ru];
                }
                head[ru] = tail[ru] = -1;
            } else {
                if (head[ru] != -1) {
                    nxt[tail[v]] = head[ru];
                    tail[v] = tail[ru];
                }
            }
        }

        comp_sum[v] = total;

        for (int j = 0; j < nroots; j++) {
            parent[roots[j]] = v;
        }
    }

    for (int i = 0; i < K; i++) {
        if (ans[i] == -1) {
            int r = find(i);
            ans[i] = comp_sum[r];
        }
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int idx = i * M + j;
            if (j > 0) printf(" ");
            printf("%lld", ans[idx]);
        }
        printf("\n");
    }

    free(nodes);
    free(parent);
    free(head);
    free(tail);
    free(nxt);
    free(comp_sum);
    free(ans);
    free(active);

    return 0;
}
